-- Rollback of 058 (market-trip BOOK Phase 2). It REFUSES, and changes nothing, when ANY Phase 2 history exists (an entry of a new kind - reversed ones included -, an
-- ALLOCATED or stock-linked book line, a TRIP_BOOK supplier settlement or its link, a marketer trip-entry leg, a v2 reconciliation record) or a later migration was applied.
-- Recorded history is never dropped or rewritten to make a rollback pass. With no such record it restores the exact 057 / 056 / 055 definitions.
SET @masgold_sql=IF(EXISTS(SELECT 1 FROM market_trip_entries WHERE entry_kind IN ('BK_ISS_STK','BK_DLV_SUP','BK_DLV_MKT','BK_RECEIVE'))
 OR EXISTS(SELECT 1 FROM market_trip_book_lines WHERE posting_basis<>'INDEPENDENT' OR stock_item_entry_id IS NOT NULL)
 OR EXISTS(SELECT 1 FROM market_trip_book_supplier_links)
 OR EXISTS(SELECT 1 FROM supplier_gold_settlements WHERE source_kind='TRIP_BOOK')
 OR EXISTS(SELECT 1 FROM marketer_gold_movements WHERE trip_entry_id IS NOT NULL)
 OR EXISTS(SELECT 1 FROM market_trip_reconciliations WHERE source_algorithm<>'book-recon-source-v1' OR snapshot_format<>'book-recon-snapshot-v1')
 OR EXISTS(SELECT 1 FROM schema_migrations WHERE version>58),
 'SELECT * FROM ROLLBACK_058_REFUSED_phase2_history_or_later_migration','DO 0');
PREPARE masgold_stmt FROM @masgold_sql; EXECUTE masgold_stmt; DEALLOCATE PREPARE masgold_stmt;
ALTER TABLE market_trip_reconciliations DROP CHECK chk_mtr_head;
ALTER TABLE market_trip_reconciliations ADD CONSTRAINT chk_mtr_head CHECK (entry_kind = 'BK_RECON' AND trip_mode = 'BOOK' AND generation >= 1 AND algorithm = 'book-recon-v1' AND source_algorithm = 'book-recon-source-v1' AND snapshot_format = 'book-recon-snapshot-v1' AND unit_denominator = 26250000 AND JSON_TYPE(snapshot) = 'OBJECT');
ALTER TABLE marketer_gold_movements DROP CHECK chk_mkgm_shape;
ALTER TABLE marketer_gold_movements ADD CONSTRAINT chk_mkgm_shape CHECK (weight_grams > 0 AND ( (document_id IS NOT NULL AND settlement_id IS NULL AND ( (movement_type = 'PURCHASE_IN' AND doc_kind = 'PURCHASE' AND weight_delta = weight_grams AND correction_id IS NULL) OR (movement_type = 'SALE_OUT' AND doc_kind = 'SALE' AND weight_delta = -weight_grams AND correction_id IS NULL) OR (movement_type = 'GOLD_RETURN' AND doc_kind = 'GOLD_RETURN' AND weight_delta = -weight_grams AND correction_id IS NULL) OR (movement_type = 'PURCHASE_IN_REVERSAL' AND doc_kind = 'PURCHASE' AND weight_delta = -weight_grams AND correction_id IS NOT NULL) OR (movement_type = 'SALE_OUT_REVERSAL' AND doc_kind = 'SALE' AND weight_delta = weight_grams AND correction_id IS NOT NULL) OR (movement_type = 'GOLD_RETURN_REVERSAL' AND doc_kind = 'GOLD_RETURN' AND weight_delta = weight_grams AND correction_id IS NOT NULL))) OR (document_id IS NULL AND doc_kind IS NULL AND settlement_id IS NOT NULL AND ( (movement_type = 'SETTLEMENT' AND weight_delta = -weight_grams AND correction_id IS NULL) OR (movement_type = 'SETTLEMENT_REVERSAL' AND weight_delta = weight_grams AND correction_id IS NOT NULL)))));
ALTER TABLE marketer_gold_movements DROP FOREIGN KEY fk_mkgm_trip_entry;
ALTER TABLE marketer_gold_movements DROP INDEX uq_mkgm_trip_entry_type;
ALTER TABLE marketer_gold_movements DROP COLUMN trip_entry_kind, DROP COLUMN trip_entry_id;
DROP TABLE IF EXISTS market_trip_book_supplier_links;
ALTER TABLE supplier_gold_settlements DROP INDEX uq_sgs_book_link;
ALTER TABLE supplier_gold_settlement_legs DROP CHECK chk_sgsl_source;
ALTER TABLE supplier_gold_settlement_legs ADD CONSTRAINT chk_sgsl_source CHECK (source_kind IN ('SHOP_SCRAP','CUSTODY_GOLD','CUSTODY_LOT','HOLDING_LOT','HOLDING_LOGO','HOLDING_MKT'));
ALTER TABLE supplier_gold_settlements DROP CHECK chk_sgs_shape;
ALTER TABLE supplier_gold_settlements ADD CONSTRAINT chk_sgs_shape CHECK ((source_kind IN ('SHOP_SCRAP','CUSTODY_GOLD') AND delivered_karat_id IS NOT NULL AND delivered_karat_value IS NOT NULL AND delivered_lot_id IS NULL AND delivered_lot_weight_grams IS NULL AND origin_melt_entry_id IS NULL AND delivered_fineness_permille IS NULL AND holding_party_id IS NULL AND lot_pool_id IS NULL AND logo_pool_id IS NULL AND physical_declaration IS NULL AND holding_weight_grams IS NULL) OR (source_kind='CUSTODY_LOT' AND delivered_karat_id IS NULL AND delivered_karat_value IS NULL AND delivered_lot_id IS NOT NULL AND delivered_lot_weight_grams IS NOT NULL AND delivered_lot_weight_grams=delivered_weight_grams AND origin_melt_entry_id IS NOT NULL AND delivered_fineness_permille IS NOT NULL AND delivered_fineness_permille>0 AND delivered_fineness_permille<=1000 AND holding_party_id IS NULL AND lot_pool_id IS NULL AND logo_pool_id IS NULL AND physical_declaration IS NULL AND holding_weight_grams IS NULL) OR (source_kind='HOLDING_LOGO' AND delivered_karat_id IS NOT NULL AND delivered_karat_value IS NOT NULL AND delivered_lot_id IS NULL AND delivered_lot_weight_grams IS NULL AND origin_melt_entry_id IS NULL AND delivered_fineness_permille IS NULL AND holding_party_id IS NOT NULL AND logo_pool_id IS NOT NULL AND lot_pool_id IS NULL AND physical_declaration IS NULL AND holding_weight_grams IS NOT NULL AND holding_weight_grams=delivered_weight_grams) OR (source_kind='HOLDING_LOT' AND delivered_karat_id IS NULL AND delivered_karat_value IS NULL AND delivered_lot_id IS NOT NULL AND delivered_lot_weight_grams IS NOT NULL AND delivered_weight_grams<=delivered_lot_weight_grams AND origin_melt_entry_id IS NOT NULL AND delivered_fineness_permille IS NOT NULL AND delivered_fineness_permille>0 AND delivered_fineness_permille<=1000 AND holding_party_id IS NOT NULL AND lot_pool_id IS NOT NULL AND logo_pool_id IS NULL AND physical_declaration IS NOT NULL AND physical_declaration IN ('WHOLE_ORIGINAL_BAR','GRAM_ENTITLEMENT','PHYSICALLY_DIVIDED') AND (physical_declaration<>'WHOLE_ORIGINAL_BAR' OR delivered_weight_grams=delivered_lot_weight_grams) AND holding_weight_grams IS NOT NULL AND holding_weight_grams=delivered_weight_grams) OR (source_kind='HOLDING_MKT' AND delivered_karat_id IS NOT NULL AND delivered_karat_value IS NOT NULL AND delivered_karat_value=21 AND delivered_lot_id IS NULL AND delivered_lot_weight_grams IS NULL AND origin_melt_entry_id IS NULL AND delivered_fineness_permille IS NULL AND holding_party_id IS NOT NULL AND lot_pool_id IS NULL AND logo_pool_id IS NULL AND physical_declaration IS NULL AND holding_weight_grams IS NOT NULL AND holding_weight_grams=delivered_weight_grams));
ALTER TABLE supplier_gold_settlements DROP CHECK chk_sgs_source;
ALTER TABLE supplier_gold_settlements ADD CONSTRAINT chk_sgs_source CHECK (source_kind IN ('SHOP_SCRAP','CUSTODY_GOLD','CUSTODY_LOT','HOLDING_LOT','HOLDING_LOGO','HOLDING_MKT'));
ALTER TABLE market_trip_book_lines DROP CHECK chk_mtbl_stock;
ALTER TABLE market_trip_book_lines DROP CHECK chk_mtbl_basis_kind;
ALTER TABLE market_trip_book_lines DROP CHECK chk_mtbl_leg;
ALTER TABLE market_trip_book_lines ADD CONSTRAINT chk_mtbl_leg CHECK ((entry_kind = 'BK_ISSUE' AND basis = 'MASTER_KARAT' AND scrap_movement_id IS NOT NULL AND line_price IS NULL) OR (entry_kind = 'BK_RETURN' AND basis = 'MASTER_KARAT' AND scrap_movement_id IS NOT NULL AND line_price IS NULL) OR (entry_kind = 'BK_RETURN' AND basis = 'FINENESS' AND scrap_movement_id IS NULL AND line_price IS NULL) OR (entry_kind IN ('BK_BUY','BK_SELL') AND scrap_movement_id IS NULL AND line_price IS NOT NULL AND line_price > 0));
ALTER TABLE market_trip_book_lines DROP CHECK chk_mtbl_posted;
ALTER TABLE market_trip_book_lines ADD CONSTRAINT chk_mtbl_posted CHECK (eq21_posted >= 0 AND eq21_analytical >= 0 AND ABS(posting_difference) <= 0.0005 AND ABS((eq21_posted - eq21_analytical) - posting_difference) <= 0.000001 AND ((direction = 'IN' AND signed_eq21_posted = eq21_posted) OR (direction = 'OUT' AND signed_eq21_posted = -eq21_posted)));
ALTER TABLE market_trip_book_lines DROP CHECK chk_mtbl_kind;
ALTER TABLE market_trip_book_lines ADD CONSTRAINT chk_mtbl_kind CHECK ((entry_kind IN ('BK_ISSUE','BK_BUY') AND direction = 'IN') OR (entry_kind IN ('BK_SELL','BK_RETURN') AND direction = 'OUT'));
ALTER TABLE market_trip_book_lines DROP FOREIGN KEY fk_mtbl_stock_item;
ALTER TABLE market_trip_book_lines DROP INDEX uq_mtbl_stock;
ALTER TABLE market_trip_book_lines DROP COLUMN stock_item_line_no, DROP COLUMN stock_item_entry_id, DROP COLUMN posting_basis;
ALTER TABLE market_trip_entries DROP CHECK chk_mte_mode_kind;
ALTER TABLE market_trip_entries ADD CONSTRAINT chk_mte_mode_kind CHECK ((trip_mode = 'LEGACY' AND entry_kind IN ('ISSUE','RETURN','MELT','LOT_RETURN','LOT_ISSUE','HEAT','SUPPLIER_PAY','GOLD_SETTLE','LOT_SETTLE','LOT_HOLD','HOLD_RETURN','LOGO_HOLD','HOLD_BACK','GOLD_SALE','GOLD_BUY')) OR (trip_mode = 'BOOK' AND entry_kind IN ('ISSUE','RETURN','SUPPLIER_PAY','BK_ISSUE','BK_BUY','BK_SELL','BK_RETURN','BK_RECON')));
ALTER TABLE market_trip_entries DROP CHECK chk_mte_kind;
ALTER TABLE market_trip_entries ADD CONSTRAINT chk_mte_kind CHECK (entry_kind IN ('ISSUE','RETURN','MELT','LOT_RETURN','LOT_ISSUE','HEAT','SUPPLIER_PAY','GOLD_SETTLE','LOT_SETTLE','LOT_HOLD','HOLD_RETURN','LOGO_HOLD','HOLD_BACK','GOLD_SALE','GOLD_BUY','BK_ISSUE','BK_BUY','BK_SELL','BK_RETURN','BK_RECON'));
DELETE FROM schema_migrations WHERE version=58;
